insert into public.programs (name, category, description, url, how_to_access, state, state_code, level, link_status, last_reviewed, program_type, source, is_published) values
  ('Alaska Housing Finance Corporation', 'energy', 'AHFC''s New Home Construction Rebate applies to new single-family residential 1- to 4-unit construction homes that achieve a 5-Star Plus or higher energy rating.', 'https://www.alaskahousingenergy.us/applicants', 'Please note that the Home Electrification and Appliance Rebate Program HER 50121 & HEAR 50122 has not launched in Alaska, so this is the only rebate available at this time (https://www.ahfc.us/efficiency/programs-for-homeowners/alaska-residential-energy-rebates)', 'Alaska', 'AK', 'state', 'Working', null, null, null, true),
  ('Recycling Programs', 'recycling', 'This website lists community recycling programs.', 'https://dec.alaska.gov/eh/solid-waste/reduce-reuse-recycle/', '', 'Alaska', 'AK', 'state', 'Blocked', null, null, null, true),
  ('Arizona Recycling Locator', 'recycling', 'Use this app to find information on e-waste, household hazardous waste (HHW), and general recycling in your community.', 'https://experience.arcgis.com/experience/6ab7b53043e64f4f917d76169e303ec6', 'Access this app via the link below.', 'Arizona', 'AZ', 'state', 'Working', null, null, null, true),
  ('Plastic Film Recycling', 'recycling', 'Use this tool to find a recycling drop off center for flexible plastic film near you.', 'https://plasticfilmrecycling.org/', '', 'Arizona', 'AZ', 'state', 'Working', null, null, null, true),
  ('Recycling Toolkit', 'recycling', 'The Recycling Toolkit is a guide to building recycling programs in Arizona, created by ADEQ in collaboration with the Arizona Recycling Coalition and Keep Arizona Beautiful.', 'https://azdeq.gov/RecyclingToolkit', '', 'Arizona', 'AZ', 'state', 'Blocked', null, null, null, true),
  ('The Arkansas Recycling Equipment Tax Credit Program', 'recycling', 'The tax credit reduces a participant''s Arkansas income tax amount due by 30 percent of the amount paid for eligible recycling equipment and installation.', 'https://www.adeq.state.ar.us/poa/enterprise-services/market/tax-credit.aspx', '', 'Arkansas', 'AR', 'state', 'Redirect', null, null, null, true),
  ('Where to Recycle', 'recycling', 'This website explains where to recycle various materials in California.', 'https://calrecycle.ca.gov/Recycle/', '', 'California', 'CA', 'state', 'Working', null, null, null, true),
  ('Colorado Home Energy Rebate Program', 'energy', 'The Colorado Home Energy Rebate Program will provide rebates to eligible Coloradans for high-efficiency electric appliances and whole-home energy efficiency upgrades. These rebates will lower upfront costs for projects that reduce energy use and make homes healthier and more comfortable.', 'https://energyoffice.colorado.gov/home-energy-rebates', '', 'Colorado', 'CO', 'state', 'Working', null, null, null, true),
  ('Tax Credits & Incentives', 'energy', 'Households earning up to 150% of the area median income can receive instant rebates through the HEAR Program when switching to electric systems and improving home insulation and efficiency.', 'https://energysmartcolorado.org/tax-credits-incentives/', '', 'Colorado', 'CO', 'state', 'Working', null, null, null, true),
  ('UPGRADE & SAVE - CT Energy Efficiency and Safety Rebate', 'energy', 'The UPGRADE & SAVE - CT Energy Efficiency and Safety Rebate offers Connecticut homeowners up to $1,000 when they install a new higher-efficiency oil-fired furnace or boiler.', 'https://upgradeandsavect.com/', '', 'Connecticut', 'CT', 'state', 'Working', null, null, null, true),
  ('Energize Connecticut', 'energy', 'Energize Connecticut (Energize CT) is a statewide initiative backed by Connecticut’s utilities and state agencies to help residents and businesses reduce their energy use and lower utility costs. Energize CT programs encompass a range of initiatives, including energy-efficient rebates, low-cost energy audits, business incentives, and electricity rate comparisons.', 'https://www.energizect.com/rebates-and-incentives', '', 'Connecticut', 'CT', 'state', 'Blocked', null, null, null, true),
  ('Connecticut energy rebates guide', 'energy', 'This is an easy to understand guide to local rebates that can help you save money on comfort and energy upgrades.', 'https://sealed.com/resources/ct-energy-rebates/', '', 'Connecticut', 'CT', 'state', 'Redirect', null, null, null, true),
  ('Recycling Program FAQ''s', 'recycling', 'This page provides general recycling FAQs for Connecticut.', 'https://portal.ct.gov/DEEP/Reduce-Reuse-Recycle/FAQs---Recycling-Program', '', 'Connecticut', 'CT', 'state', 'Working', null, null, null, true),
  ('Connecticut Low Income Household Water Assistance Program (LIHWAP)', 'water', 'If you receive benefits from the Connecticut Energy Assistance Program, SNAP, TFA, SSI, State Supplement, or Refugee Cash, then you likely meet the income requirements to qualify for water assistance.', 'https://portal.ct.gov/DSS/Highlights/Low-Income-Household-Water-Assistance-Program-Coming-to-CT/How-To-Apply?language=en_US', '', 'Connecticut', 'CT', 'state', 'Working', null, null, null, true),
  ('Energize Delaware', 'energy', 'The Home Efficiency Rebate Program and Home Electrification and Appliance Rebate Program, which are expected to launch once funding is received later this year, are designed to help Delawareans reduce home energy costs.', 'https://energizedelaware.org/residential/', '', 'Delaware', 'DE', 'state', 'Working', null, null, null, true),
  ('Home Energy Rebate Programs', 'energy', 'Save on energy-efficient upgrades with rebates, assistance programs, and solar incentives.', 'https://energizedelaware.org/residential/', '', 'Delaware', 'DE', 'state', 'Working', null, null, null, true),
  ('Delaware Solar Incentives, Tax Credits And Rebates', 'energy', 'This page provides a table featuring five solar panel rebates.', 'https://www.forbes.com/home-improvement/solar/delaware-solar-incentives/', '', 'Delaware', 'DE', 'state', 'Blocked', null, null, null, true),
  ('Recyclopedia: What Can I Recycle in Delaware', 'recycling', 'Use the Recyclopedia search tool to find out if something is acceptable to recycle at home, if you need to drop it off, or if it is trash.', 'https://dnrec.delaware.gov/waste-hazardous/recycling/what/#/locationSelection', '', 'Delaware', 'DE', 'state', 'Working', null, null, null, true),
  ('Florida Energy Saver program', 'energy', 'The Home Electrification and Appliance Rebates (HEAR) and Home Efficiency Rebates (HOMES) programs are expected to launch in the future. If you are interested in participating, please register or sign in if you already have an account.', 'https://floridaenergysaverprogram.fdacs.gov/en-US', 'If you are interested in participating, please register or sign in if you already have an account. See link below for more information.', 'Florida', 'FL', 'state', 'Working', null, null, null, true),
  ('Florida Recycling', 'recycling', 'This page provides general information about recycling in Florida. Find information about resources at the bottom of the page.', 'https://floridadep.gov/waste/waste-reduction/content/recycling', 'Find information about resources at the bottom of the page via the link below.', 'Florida', 'FL', 'state', 'Working', null, null, null, true),
  ('Georgia''s Home Energy Rebates', 'energy', 'Georgia’s Home Energy Rebates provide households with incentives on the purchase and installation of electric appliances, insulation, air sealing, HVAC, and other home improvement measures. Eligible households can get up to $16,000 in savings depending on their household income and/or expected energy savings.', 'https://energyrebates.georgia.gov/', '', 'Georgia', 'GA', 'state', 'Working', null, null, null, true),
  ('Hawaii State Energy Office', 'energy', 'This page provides information about several energy incentives in Hawaii.', 'https://energy.hawaii.gov/rebates-and-incentives/', '', 'Hawaii', 'HI', 'state', 'Working', null, null, null, true),
  ('Recycling & Waste', 'recycling', 'This page provides links to information about recycling for different parts of Hawaii.', 'https://portal.ehawaii.gov/residents/recycling-and-waste/', '', 'Hawaii', 'HI', 'state', 'Working', null, null, null, true),
  ('Idaho Energy and Mineral Resources Governor''s Office of Energy and Mineral Resources', 'energy', 'This website provides information about programs and incentives, tax credits and deductions, and federal resources.', 'https://oemr.idaho.gov/financial-information/incentives/', '', 'Idaho', 'ID', 'state', 'Working', null, null, null, true),
  ('Idaho Department of Environmental Quality', 'recycling', 'This is an information page about recycling in Idaho.', 'https://www.deq.idaho.gov/waste-management-and-remediation/solid-waste/recycling-reuse-and-composting/', '', 'Idaho', 'ID', 'state', 'Working', null, null, null, true),
  ('Illinois Solar for All', 'energy', 'Eligible households or organizations can get affordable solar energy for no or low upfront costs.', 'https://www.illinoissfa.com/', '', 'Illinois', 'IL', 'state', 'Working', null, null, null, true),
  ('Energy Rebates', 'energy', 'IRA Home Energy Resources and Energy Efficiency Funding for Illinois residents.', 'https://epa.illinois.gov/topics/energy/energy-rebates.html', '', 'Illinois', 'IL', 'state', 'Working', null, null, null, true),
  ('EnergySense Resilience Center', 'energy', 'State and federal funding opportunities for clean energy, including energy efficiency and incentives.', 'https://energysense.uillinois.edu/illinois-incentives/', '', 'Illinois', 'IL', 'state', 'Working', null, null, null, true),
  ('EPA Beyond the Bin Map', 'recycling', 'Filter by recycling material to find recycling locations near you.', 'https://illinois-epa.maps.arcgis.com/apps/webappviewer/index.html?id=1e86d9a5913a4ca49fb0cfd64f1c2872', 'Filter by recycling material to find recycling locations near you.', 'Illinois', 'IL', 'state', 'Working', null, null, null, true),
  ('Electric Vehicle Rebate Program', 'transportation', 'Use this program to apply for an EV rebate in Illinois today!', 'https://epa.illinois.gov/topics/ceja/electric-vehicle-rebates.html', '', 'Illinois', 'IL', 'state', 'Working', null, null, null, true),
  ('Environmental Quality Incentives Program', 'water', 'The Environmental Quality Incentives Program (EQIP) provides financial and technical assistance to agricultural producers and non-industrial forest managers to conserve natural resources while strengthening their operations.', 'https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/indiana/environmental-quality', '', 'Indiana', 'IN', 'state', 'Working', null, null, null, true),
  ('Indiana Energy Saver Program', 'energy', 'The Indiana Energy Saver Program will provide cost savings through two program offerings: the Home Efficiency Rebates (HOMES) and the Home Appliance Rebates (HEAR).', 'https://indianaenergysaver.com/', '', 'Indiana', 'IN', 'state', 'Working', null, null, null, true),
  ('Indiana Laws and Incentives', 'transportation', 'Listed below are incentives, laws, and regulations related to alternative fuels and advanced vehicles for Indiana.', 'https://afdc.energy.gov/laws/state_summary?state=in', '', 'Indiana', 'IN', 'state', 'Working', null, null, null, true),
  ('Residential Energy Efficiency and Electrification Programs', 'energy', 'The home energy rebates will help households save money on energy bills, upgrade to clean energy equipment, and improve energy efficiency.', 'https://opportunityiowa.gov/community/energy/grants-funding/residential-energy-efficiency-programs', '', 'Iowa', 'IA', 'state', 'Working', null, null, null, true),
  ('Multifamily Energy Audit Program', 'energy', 'The Iowa Economic Development Authority (IEDA) provides federal grant funds for the completion of energy audits and the improvement of lighting energy efficiency at multifamily housing properties.', 'https://opportunityiowa.gov/community/energy/grants-funding/multifamily-energy-audit-program', '', 'Iowa', 'IA', 'state', 'Working', null, null, null, true),
  ('Soil Conservation and Water Quality Cost Share Assistance', 'water', 'Your local Soil and Water Conservation District administers numerous programs supported by the Iowa Department of Agriculture and Land Stewardship, which can provide partial financial assistance to address farmers’ and landowners’ soil conservation and water quality concern.', 'https://costshare.iowaagriculture.gov/', '', 'Iowa', 'IA', 'state', 'Working', null, null, null, true),
  ('Iowa Laws and Incentives', 'transportation', 'Listed below are incentives, laws, and regulations related to alternative fuels and advanced vehicles for Iowa.', 'https://afdc.energy.gov/laws/state_summary?state=IA', '', 'Iowa', 'IA', 'state', 'Working', null, null, null, true),
  ('Kansas Energy Office Programs and Incentives', 'energy', 'Tax credits, rebates, and savings related to energy usage in Kansas.', 'https://programs.dsireusa.org/system/program/ks', '', 'Kansas', 'KS', 'state', 'Working', null, null, null, true),
  ('Individual Water and Wastewater Grants', 'water', 'Applications for this program are accepted year-round. Please apply through your local Rural Development office.', 'https://www.rd.usda.gov/programs-services/single-family-housing-programs/individual-water-wastewater-grants/ks', 'Please apply through your local Rural Development office.', 'Kansas', 'KS', 'state', 'Blocked', null, null, null, true),
  ('Natural Resources Conservation Service', 'water', 'The Natural Resources Conservation Service offers technical and financial assistance to help farmers, ranchers, and landowners.', 'https://www.kacd.net/usda-nrcs.cfm', '', 'Kansas', 'KS', 'state', 'Working', null, null, null, true),
  ('Regenerative Ag and Soil Health Initiatives', 'water', 'To learn more about these programs, producers can reach out to their local Conservation District.', 'https://www.kacd.net/advancing-markets-for-producers.cfm', '', 'Kansas', 'KS', 'state', 'Working', null, null, null, true),
  ('Kansas Reservoir Protection Initiative', 'water', 'KRPI provides financial assistance to landowners for the implementation of sediment-reducing practices on lands upstream of multiple reservoirs.', 'https://www.kacd.net/kansas-reservoir-protection-initiative.cfm', '', 'Kansas', 'KS', 'state', 'Working', null, null, null, true),
  ('Kansas WRAPS (Watershed Restoration and Protection Strategies)', 'water', 'The Kansas WRAPS process offers a framework that engages citizens and other stakeholders in a teamwork environment aimed at protecting and restoring Kansas watersheds.', 'https://www.kacd.net/kansas-wraps.cfm', '', 'Kansas', 'KS', 'state', 'Working', null, null, null, true),
  ('Specialty Crops and Urban Ag', 'water', 'Districts are able to deliver technical and financial assistance to a broad spectrum of producers, from aspiring to experienced, small to medium-scale, in the diverse urban, suburban, and rural communities across Kansas.', 'https://www.kacd.net/specialty-crops-and-urban-ag.cfm', '', 'Kansas', 'KS', 'state', 'Working', null, null, null, true),
  ('State Cost-Share Program', 'water', 'The Kansas Department of Agriculture, Division of Conservation (DOC), works to protect and enhance Kansas’ natural resources through programs designed to assist local conservation district boards and individuals in conserving the state’s renewable resources.', 'https://www.kacd.net/state-cost-share.cfm', '', 'Kansas', 'KS', 'state', 'Working', null, null, null, true),
  ('Kansas Laws and Incentives', 'transportation', 'Listed below are incentives, laws, and regulations related to alternative fuels and advanced vehicles for Kansas.', 'https://afdc.energy.gov/laws/state_summary?state=KS', '', 'Kansas', 'KS', 'state', 'Working', null, null, null, true),
  ('Energy Incentive and Policies', 'energy', 'Listed below are energy incentives for Kentucky.', 'https://programs.dsireusa.org/system/program?state=TER', '', 'Kentucky', 'KY', 'state', 'Working', null, null, null, true),
  ('Louisiana Laws and Incentives', 'transportation', 'Listed below are incentives, laws, and regulations related to alternative fuels and advanced vehicles for Louisiana.', 'https://afdc.energy.gov/laws/state_summary?state=la', '', 'Louisiana', 'LA', 'state', 'Working', null, null, null, true),
  ('Energy Incentive and Policies', 'energy', 'Listed below are energy incentives for Louisiana.', 'https://programs.dsireusa.org/system/program?state=TER', '', 'Louisiana', 'LA', 'state', 'Working', null, null, null, true),
  ('Efficiency Maine', 'energy', 'Click on "rebates" and "solutions" for home energy, water, and appliance rebates. Residents can also check the website’s "Green Bank" page. Efficiency Maine also offers home energy loans to help homeowners pay for qualifying energy upgrades.', 'https://www.efficiencymaine.com/', 'Click on "rebates" and "solutions" for home energy, water, and appliance rebates. Residents can also check the website’s "Green Bank" page.', 'Maine', 'ME', 'state', 'Working', null, null, null, true),
  ('MaineHousing programs', 'energy', 'This program can help you pay for heating your home, electric bills, and energy improvements like new insulation or heating systems.', 'https://www.mainehousing.org/programs-services/energy', '', 'Maine', 'ME', 'state', 'Working', null, null, null, true),
  ('Maine Laws and Incentives', 'transportation', 'EV rebates (that’s it). Utilities/private entities. Check Maine Clean Communities.', 'https://afdc.energy.gov/laws/state_summary?state=ME', 'Check Maine Clean Communities via link below.', 'Maine', 'ME', 'state', 'Server Error', null, null, null, true),
  ('EmPOWER program', 'energy', 'Utilities must have incentives to help individuals switch from fossil fuel-powered heating and appliances to efficient, electric alternatives.', 'https://energy.maryland.gov/pages/facts/empower.aspx', '', 'Maryland', 'MD', 'state', 'Working', null, null, null, true),
  ('Maryland Energy Administration', 'energy', 'Visit the Maryland Energy Administration website and look under grants and incentives for residential programs. The page includes options for storage, solar, geothermal rebates, community solar, clean energy rebates, energy equity grants, and energy storage tax credits.', 'https://energy.maryland.gov/Pages/all-incentives.aspx', 'Visit the Maryland Energy Administration website and look under ''Grants, Loans, Rebates, and Other Incentives'' for residential programs.', 'Maryland', 'MD', 'state', 'Working', null, null, null, true),
  ('Maryland Laws and Incentives', 'transportation', 'This page lists EV and fuel cell vehicle tax credits, EV charger rebates, HOV lane exemptions, and other related incentives, including utility and private entity resources.', 'https://afdc.energy.gov/laws/state_summary?state=MD', '', 'Maryland', 'MD', 'state', 'Server Error', null, null, null, true),
  ('Titling - Excise Tax Credit for Plug-in Electric Vehicles', 'transportation', 'Excise Tax Credit for Plug-in Electric or Fuel Cell Vehicles', 'https://mva.maryland.gov/your-mva-guide/businesses/bulletins-businesses/excise-tax-credit-plug-electric-or-fuel-cell-vehicles-no-more-fiscal-year-2026-funding', 'The Motor Vehicle Administration (MVA) reports that the Fiscal Year 2026 funds for the EV excise tax credit are depleted. They will, however, continue to accept applications and place applicants on a waiting list.', 'Maryland', 'MD', 'state', 'Working', null, null, null, true),
  ('Energy Rebates & Incentives', 'energy', 'List of federal and state rebates for Minnesota.', 'https://www.mass.gov/guides/massachusetts-energy-rebates-incentives', '', 'Massachusetts', 'MA', 'state', 'Redirect', null, null, null, true),
  ('home energy efficiency tax credits', 'energy', 'You can sign up for the "Consumer Announcements" newsletter for information on rebates, grants, and incentives. Scroll down to the "Consumers" section for additional programs. The page also includes EV information and renter resources, although EV rebates are currently unavailable.', 'https://www.michiganlcv.org/save-money-with-home-energy-efficiency-tax-credits/', 'Sign up for the "Consumer Announcements" newsletter for information on rebates, grants, and incentives. Scroll down to the "Consumers" section for additional programs.', 'Michigan', 'MI', 'state', 'Working', null, null, null, true),
  ('State of Michigan Community EV Toolkit', 'transportation', 'The State of Michigan Community EV Toolkit gives local communities and stakeholders quick access to key data and background information, the current status of EV registration, infrastructure and deployment, community zoning and planning ordinances, community fleet electrification, funding opportunities, and local best practices.', 'https://southeast-michigan-ev-resource-kit-and-planning-hub-semcog.hub.arcgis.com/', '', 'Michigan', 'MI', 'state', 'Working', null, null, null, true),
  ('Michigan Laws and Incentives', 'transportation', 'This page lists EV toll lane credits and EV rebates. Some utility information may be outdated, especially at the local level, so it is best to check your local utility website.', 'https://afdc.energy.gov/laws/all?state=MI', '', 'Michigan', 'MI', 'state', 'Working', null, null, null, true),
  ('Save Energy Minnesota', 'energy', 'This provides bill help for HEAP (or LIHEAP).', 'https://mn.gov/commerce/energy/consumer/energy-programs/save-energy-mn.jsp', '', 'Minnesota', 'MN', 'state', 'Working', null, null, null, true),
  ('New Energy Programs', 'energy', 'Save Energy Minnesota combines state and federal rebate programs to support energy-efficient home improvements. It offers several rebate options to help make clean energy upgrades more affordable for communities and residents across Minnesota.', 'https://mn.gov/commerce/energy/consumer/energy-programs/save-energy-mn.jsp', 'Current update (6/12/2026): Save Energy Minnesota has not launched yet. Minnesota is waiting for formal approval from US Department of Energy (DOE) to launch the program. See link below', 'Minnesota', 'MN', 'state', 'Working', null, null, null, true),
  ('Free Water Conservation Kit', 'water', '', 'https://www.minnesotaenergyresources.com/savings/water-conservation', '', 'Minnesota', 'MN', 'state', 'Working', null, null, null, true),
  ('Minnesota Laws and Incentives', 'transportation', '', 'https://afdc.energy.gov/laws/all?state=MN', '', 'Minnesota', 'MN', 'state', 'Working', null, null, null, true),
  ('Office of Energy', 'energy', 'This page explains how to find an energy auditor. It does not provide financial assistance, but an audit can help identify cost effective measures.', 'https://mississippi.org/community-resources/office-of-energy/', '', 'Mississippi', 'MS', 'state', 'Working', null, null, null, true),
  ('Department of Revernue', 'energy', '', 'https://dor.mo.gov/taxation/business/tax-types/sales-use/holidays/show-me-green/', '', 'Missouri', 'MO', 'state', 'Working', null, null, null, true),
  ('Inflation Reduction Act (IRA) Home Energy Rebates Programs', 'energy', 'The Missouri Department of Natural Resources held public meetings to discuss the rebates and planned state programs. On Nov. 22, 2024, the department submitted the state’s application to DOE to receive these funds. Please note that details about rebate eligibility and how to apply are not finalized at this time. The department cannot provide an estimate as to when rebates will be available to the public. The rebates may not be made available until 2027 at the earliest and potentially as late as 2028.', 'https://dnr.mo.gov/energy/what-were-doing/inflation-reduction-act-home-energy-rebates-programs', 'Rebates not available yet. See link below for more information.', 'Missouri', 'MO', 'state', 'Redirect', null, null, null, true),
  ('Energy Financial Assistance Opportunities', 'energy', 'In the website, tap on interested energy programs, which link to more detailed information.', 'https://dnr.mo.gov/energy/financial-assistance-opportunities', 'On the website, tap on interested energy programs, which link to more detailed information.', 'Missouri', 'MO', 'state', 'Working', null, null, null, true),
  ('Home Energy Audits', 'energy', 'Alternative energy revolving loan programs list loan amounts, terms, and application deadlines.', 'https://dnr.mo.gov/energy/efficiency/home-audits', '', 'Missouri', 'MO', 'state', 'Working', null, null, null, true),
  ('Wood Energy Tax Credit', 'energy', 'In the website, tap on categories of recyclables of interest.', 'https://dnr.mo.gov/energy/financial-assistance-opportunities/wood-energy-tax-credit', 'On the website, tap on categories of recyclables of interest.', 'Missouri', 'MO', 'state', 'Working', null, null, null, true),
  ('Water Financial Assistance Opportunities', 'water', 'In the website, access local drop-off sites and contact information.', 'https://dnr.mo.gov/water/financial-assistance-opportunities', '', 'Missouri', 'MO', 'state', 'Working', null, null, null, true),
  ('Montana State Energy Programs', 'energy', 'This is the composting grant applications and criteria.', 'https://deq.mt.gov/energy/', '', 'Montana', 'MT', 'state', 'Working', null, null, null, true),
  ('Alternative Energy Revolving Loan Program | Montana DEQ', 'energy', 'Alternative energy revolving loan programs provide information on loans, terms, and application deadlines.', 'https://deq.mt.gov/energy/Programs/AERLP', '', 'Montana', 'MT', 'state', 'Working', null, null, null, true),
  ('WasteNet Program-Recycle', 'recycling', 'Tap on the categories of recyclables that interest you to access local drop off sites and contact information.', 'https://www.wastenotproject.org/recycle/', 'Tap on the categories of recyclables that interest you to access local drop off sites and contact information.', 'Montana', 'MT', 'state', 'Working', null, null, null, true),
  ('Recycle Montana', 'recycling', 'This page explains composting grant applications and criteria.', 'https://www.recyclemontana.org/grants/recycling-project-of-your-choice-grant', '', 'Montana', 'MT', 'state', 'Working', null, null, null, true),
  ('Montana Watershed Coordination Council Watershed Fund', 'water', '', 'https://www.mtwatersheds.org/support/mwcc-grants/', '', 'Montana', 'MT', 'state', 'Working', null, null, null, true),
  ('Montana Clean Water', 'water', 'This link provides access to documents available for protecting your right to access clean water.', 'https://www.montanacleanwater.com/forms-documents', '', 'Montana', 'MT', 'state', 'Working', null, null, null, true),
  ('Montana Water Funding sources', 'water', 'This page links to agencies that provide funding for community development needs or bond financing for eligible governments. Tap on the targeted community or government funds to view contact information and links to fund websites.', 'https://www.montanawater.org/links-things/funding-sources/', 'Tap on the targeted community or government funds to view contact information and links to fund websites.', 'Montana', 'MT', 'state', 'Working', null, null, null, true),
  ('NC Clean Energy Technology Center Net Metering', 'energy', 'Nebraska offers net metering for residential renewable systems (solar, wind, etc.) up to 25 kW, crediting excess energy sent to the grid at the retail rate, though policies can vary by utility and focus is on bill reduction rather than cash payments, with potential for carryover credits.', 'https://programs.dsireusa.org/system/program/detail/3386', '', 'Nebraska', 'NE', 'state', 'Working', null, null, null, true),
  ('The Waste Reduction and Recycling Incentive Grants Fund', 'recycling', 'The Waste Reduction and Recycling Incentive Grants Fund provides grants to support integrated waste management programs and projects. Application links are provided in blue below the grant funding section.', 'https://dee.nebraska.gov/land-waste/landfill-disposal-fee-rebate-program/litter-waste-reduction-and-recycling-incentive-grants', 'Application links are provided in blue below the grant funding section.', 'Nebraska', 'NE', 'state', 'Redirect', null, null, null, true),
  ('Recycling Equipment Grant (REG) Program', 'recycling', 'The Nebraska Recycling Council administers the Recycling Equipment Grant Program with funding from the Nebraska Environmental Trust. Scroll down to the blue "Apply Today" button and complete the Adobe fillable PDF application.', 'https://nrcne.org/recycling-equipment-grants/', 'Scroll down to the blue "Apply Today" button and complete the Adobe fillable PDF application.', 'Nebraska', 'NE', 'state', 'Working', null, null, null, true),
  ('The Nebraska Clean Water State Revolving Loan Fund (CWSRF) program', 'water', 'The Nebraska Clean Water State Revolving Loan Fund provides low interest loans and small community matching grants to municipalities for wastewater treatment and sanitary sewer projects. Residents can contact the program at 402-471-4200 for guidance through the planning process.', 'https://dee.nebraska.gov/aid/water-loans-grants-rebates/clean-water-state-revolving-loan-fund-wastewater-treatment-facilities-and-sanitary-sewer-collection-systems', 'Residents can contact the program at 402-471-4200 for guidance through the planning process.', 'Nebraska', 'NE', 'state', 'Redirect', null, null, null, true),
  ('Alternative Fuels Data Center State Incentives', 'transportation', 'Under the state incentives section, tax credit and tax refund resources are listed.', 'https://afdc.energy.gov/laws/state_summary?state=NE', 'View the ''State Incentives'' section for information.', 'Nebraska', 'NE', 'state', 'Working', null, null, null, true),
  ('The Clean Energy Plan', 'energy', 'The Clean Energy Plan provides financial incentives to Nevada residents, businesses, schools, and nonprofits for clean energy and energy efficiency improvements. Enter your household information and press "View Results" to see the available funding.', 'https://www.nevadaconservationleague.org/clean-energy-plan/', 'Enter your household information and press "View Results" to see the available funding.', 'Nevada', 'NV', 'state', 'Working', null, null, null, true),
  ('Free Nevada Solar Incentives', 'energy', 'This page explains Nevada solar incentives. To apply for free solar panel installation, click "Click Here to Sign Up for Free Solar Panel Installation," complete the State Solar Registry, and submit the form. To apply for the federal solar tax credit, scroll to the section on how to claim the credit and follow the listed steps.', 'https://nevada.statesolar.org/', 'To apply for free solar panel installation, click "Click Here to Sign Up for Free Solar Panel Installation," complete the State Solar Registry, and submit the form. To apply for the federal solar tax credit, scroll to the section on how to claim the credit and follow the listed steps.', 'Nevada', 'NV', 'state', 'Working', null, null, null, true),
  ('Renewable Energy Tax Abatements', 'energy', 'Renewable Energy Tax Abatements award partial sales and use tax abatements and partial property tax abatements to eligible renewable energy facilities. The application steps and timeline are listed under the Renewable Energy Tax Abatement Application section.', 'https://www.energy.nv.gov/programs/renewable-energy-tax-abatement-reta-program/', 'The application steps and timeline are listed under the Renewable Energy Tax Abatement Application section.', 'Nevada', 'NV', 'state', 'Working', null, null, null, true),
  ('Nevada Recycle Grants', 'recycling', 'Nevada Recycling has two locations for dumping and dumpster rental services.', 'https://www.nevadarecycling.com/', '', 'Nevada', 'NV', 'state', 'Working', null, null, null, true),
  ('Alternative Fuels Data Center State Incentives', 'transportation', 'The Alternative Fuels Data Center lists Nevada incentives, including exemptions from emission testing requirements for alternative fuel vehicles.', 'https://afdc.energy.gov/laws/all?state=NV', '', 'Nevada', 'NV', 'state', 'Working', null, null, null, true),
  ('Refrigerator & Freezer Recycling', 'recycling', 'Recycling a refrigerator or freezer may qualify for a $75 rebate. Tap "Get Started" and fill in your information.', 'https://nhsaves.com/residential/refrigerator-and-freezer-recycling/', 'Tap "Get Started" and fill in your information on the site.', 'New Hampshire', 'NH', 'state', 'Working', null, null, null, true),
  ('NHSaves', 'energy', 'Your NHSaves utility partners offer a wide variety of rebates on the products and technologies that help New Hampshire residents save energy.', 'https://nhsaves.com/rebates-services-appliances/', '', 'New Hampshire', 'NH', 'state', 'Blocked', null, null, null, true),
  ('The PFAS Removal Rebate Program for Private Wells', 'water', 'The PFAS Removal Rebate Program for Private Wells provides rebates to private residential well owners of up to $5,000 for the installation of a treatment system designed to remove per- and polyfluoroalkyl substances (PFAS) or up to $10,000 for a service connection to a public water system.', 'https://www.pfas.des.nh.gov/funding/pfas-removal-rebate-program-private-wells', '', 'New Hampshire', 'NH', 'state', 'Working', null, null, null, true),
  ('NJCEP’s Energy Efficiency Programs', 'energy', 'This government website posts programs that support more energy efficient lifestyles. Check the programs listed under NJCEP’s Energy Efficiency Programs that are marked "Applications are open" and fill out the interest form.', 'https://cleanenergy.nj.gov/programs/energy-efficiency', 'Check the programs listed under NJCEP’s Energy Efficiency Programs that are marked "Applications are open" and fill out the interest form.', 'New Jersey', 'NJ', 'state', 'Working', null, null, null, true),
