  ('The New Jersey Department of Environmental Protection (DEP)', 'recycling', 'This page lists incentives in areas such as recycling and litter abatement.', 'https://dep.nj.gov/sustainability/steps-to-sustainability/funding-and-incentives/', '', 'New Jersey', 'NJ', 'state', 'Working', null, null, null, true),
