  ('New Jersey''s Clean Energy Program', 'transportation', 'New Jersey''s Clean Energy Program offers incentives for Level 2 and DC fast chargers for businesses, hotels, attractions, and other destinations along key travel routes. Check the eligibility requirements and potential incentive amounts, then tap "Apply for Incentive" to begin.', 'https://chargeup.njcleanenergy.com/ev-tourism-corridor', 'Check the eligibility requirements and potential incentive amounts, then tap "Apply for Incentive" to begin.', 'New Jersey', 'NJ', 'state', 'Working', null, null, null, true),
  ('New Jersey zero-emission incentive program', 'transportation', 'The New Jersey zero emission incentive program reduces the up front cost of eligible medium and heavy duty zero emission vehicles. Scroll down to the green "Phase 3 Information" section and tap the green "Apply Here" button.', 'https://www.njeda.gov/njzip/', 'Scroll down to the green "Phase 3 Information" section and tap the green "Apply Here" button.', 'New Jersey', 'NJ', 'state', 'Working', null, null, null, true),
