  ('Alternative Fuels Data Center', 'transportation', 'Select your state to see tax credits available for alternative fuels and EVs (state and federal). You can find more information on how to use this on your state''s page.', 'https://afdc.energy.gov/laws', 'You can find more information on how to use this on your state''s page.', 'US', null, 'federal', 'Working', null, null, null, true),
  ('WaterSense Rebate Finder', 'water', 'This is a database of conservation services and rebates for water-efficient toilets, showerheads, faucets, sprinklers, and other water appliances. Select your state and click on the "Residential" section to see if your town appears on the list.', 'https://lookforwatersense.epa.gov/Rebate-Finder.html', 'Select your state and "Residential," and see if your town appears on the list.', 'US', null, 'federal', 'Working', null, null, null, true),
  ('Alternative Fueling Station Locator', 'transportation', 'This map shows you nearby alternative fueling stations (biodiesel, hydrogen, electric,etc.).', 'https://afdc.energy.gov/stations#/find/nearest', '', 'US', null, 'federal', 'Working', null, null, null, true),
  ('Energy Star', 'water', 'A government website that provides savings on energy efficient home appliances, called ENERGY STAR certified products. Enter your ZIP code to find rebates and special offers near you on ENERGY STAR certified products.', 'https://www.energystar.gov/', 'Enter your ZIP code to find rebates and special offers near you on ENERGY STAR certified products.', 'US', null, 'federal', 'Working', null, null, null, true),
  ('HEAP', 'energy', 'The Low Income Home Energy Assistance Program provides monetary assistance for paying home energy bills, addressing energy crises, weatherization, and minor energy-related home repairs. Go to the linked website and click "Get Assistance" to see if you qualify for next steps.', 'https://www.liheap.org/', 'Go to the linked website and click "Get Assistance" to see if you qualify then follow the next steps.', 'US', null, 'federal', 'Working', null, null, null, true),
  ('Residential Clean Energy Credit', 'energy', 'The Residential Clean Energy Credit covers 30% of the costs of new, qualified clean energy property for your home installed between 2022 and December 31, 2025. Detailed instructions for how this energy credit works and the qualified expenses are provided here by the IRS.', 'https://www.irs.gov/credits-deductions/residential-clean-energy-credit', 'Detailed instructions for how this energy credit works and the qualified expenses are provided here by the IRS.', 'US', null, 'federal', 'Working', null, null, null, true),
